use vstd::prelude::*;

verus! {
    // Specification for the solve function
    fn solve(a: i8) -> (count: i8)
        requires
            a >= 0, // a must be non-negative
        ensures
            count == count_octal_ones(a as nat), // Ensures the count of '1's in octal representation
    {
        // Convert i8 to u8 for easier manipulation since we know a is nonnegative
        let mut v = a as u8;
        let mut count = 0;

        while v > 0
            invariant
                v <= a as u8, // v should not exceed the original value of a
                count >= 0, // count should always be non-negative
                count == count_octal_ones((a as nat) - (v as nat)), // Count of '1's in the octal representation so far
            decreases v,
        {
            // Check if the least significant octal digit is 1
            if v % 8 == 1 {
                count += 1;
            }
            // Move to the next digit in octal representation
            v /= 8;
        }

        count as i8 // Convert back to i8 before returning
    }

    // Helper function to count the number of '1's in the octal representation of a non-negative integer
    spec fn count_octal_ones(n: nat) -> nat
        decreases n,
    {
        if n == 0 {
            0
        } else {
            (if n % 8 == 1 { 1 } else { 0 }) + count_octal_ones(n / 8)
        }
    }
}
